shell_commands:
python3 - <<'EOF'
p='src/orchestration/tools/registry.ts'
s=open(p).read()
s=s.replace("""  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
""","""  private compileStatic(definition: ToolDefinition): void {
    if (!this.ajv.validateSchema(definition.inputSchema)) {
      const reason = this.ajv.errorsText(this.ajv.errors, {dataVar: 'schema'});
      throw new Error(`Invalid inputSchema for tool ${definition.name}: ${reason}`);
    }
    this.validatorFor(definition.inputSchema);
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    if (typeof definition !== 'function') this.compileStatic(resolved);
""")
open(p,'w').write(s)
EOF
